import React, { useState } from 'react';
import PixelPerson, {
  SKIN_TONES, HAIR_COLORS, PANTS_COLORS,
  HAIR_STYLES, HAIR_STYLE_LABELS,
  HATS, HAT_LABELS, POSES, POSE_LABELS,
} from './PixelPerson';

const FONT = "'Press Start 2P', monospace, 'Noto Sans Thai', sans-serif";

const C = {
  bg: '#FDF0E8', text: '#3D2010', sub: '#A07850',
  orange: '#F4956A', orangeLight: '#FFF0E8', orangeDark: '#C05E35',
  purple: '#A78BFA', purpleLight: '#FAF5FF', purpleDark: '#7C3AED',
  green:  '#5DCAA5', greenLight:  '#F0FDFA', greenDark:  '#0D9488',
  yellow: '#F9C784', yellowLight: '#FEF3C7', yellowDark: '#D4900A',
  blue:   '#93C5FD', blueLight:   '#EFF6FF', blueDark:   '#2563EB',
};

const pxBox = (bc, sd, sl, drop) => ({
  background: '#fff', border: `4px solid ${bc}`, borderRadius: 0,
  boxShadow: `inset -3px -3px 0 ${sd}, inset 3px 3px 0 ${sl}, 4px 4px 0 ${drop}`,
});

// ── Outfit presets as costume cards ─────────────────────────────
const OUTFIT_PRESETS = [
  { color:'#5B8DEF', label:'น้ำเงิน' },
  { color:'#EF5B5B', label:'แดง'     },
  { color:'#5BCE8A', label:'เขียว'   },
  { color:'#F4956A', label:'ส้ม'     },
  { color:'#A78BFA', label:'ม่วง'    },
  { color:'#F9C784', label:'เหลือง'  },
  { color:'#EC4899', label:'ชมพู'    },
  { color:'#64748B', label:'เทา'     },
  { color:'#38BDF8', label:'ฟ้า'     },
];

const PANTS_PRESETS = PANTS_COLORS.map((color, index) => ({
  color,
  label: ['เขียว', 'น้ำเงิน', 'น้ำตาล', 'ดำ', 'ม่วง', 'เหลือง', 'เทา', 'ชมพู'][index],
}));

export default function ProfilePage({ profile, setProfile }) {
  const [tab, setTab]           = useState('avatar'); // 'avatar' | 'outfit' | 'info'
  const [saveFlash, setSaveFlash] = useState(false);

  // ── Profile update helpers ────────────────────────────────────
  const update = (key, val) => {
    const next = { ...profile, [key]: val };
    setProfile(next);
    localStorage.setItem('profile', JSON.stringify(next));
  };

  const saveAll = () => {
    localStorage.setItem('profile', JSON.stringify(profile));
    setSaveFlash(true);
    setTimeout(() => setSaveFlash(false), 2000);
  };

  // ── Swatch helper ─────────────────────────────────────────────
  const Swatch = ({ color, active, onClick }) => (
    <button onClick={onClick} style={{
      width: 34, height: 34, background: color, cursor: 'pointer',
      border: `3px solid ${active ? '#1a1a1a' : '#C8B8A8'}`,
      boxShadow: active ? `2px 2px 0 #1a1a1a` : 'none', outline: 'none',
      flexShrink: 0,
    }}/>
  );

  return (
    <div style={{ fontFamily: FONT }}>

      {/* ── Header ── */}
      <div style={{ display:'flex', alignItems:'center', gap:14, marginBottom:20 }}>
        <div style={{
          background: C.purple, border:`3px solid ${C.purpleDark}`,
          boxShadow:`2px 2px 0 #4a1aa0`, padding:'9px 11px',
        }}>
          <span style={{ fontSize:18 }}>👤</span>
        </div>
        <div>
          <h2 style={{ margin:0, fontSize:16, fontWeight:700, color:C.text, fontFamily:FONT, lineHeight:1.8 }}>โปรไฟล์</h2>
          <p style={{ margin:0, fontSize:11, color:C.sub, fontFamily:FONT }}>แต่งตัวละครของคุณ</p>
        </div>
      </div>

      {/* ── Tabs ── */}
      <div style={{ display:'flex', gap:8, marginBottom:20 }}>
        {[
          { key:'avatar', label:'🎨 ตัวละคร' },
          { key:'outfit', label:'👕 เปลี่ยนชุด' },
          { key:'info',   label:'📝 ข้อมูล' },
        ].map(t => (
          <button key={t.key} onClick={() => setTab(t.key)} style={{
            padding:'12px 18px', borderRadius:0, fontFamily:FONT, cursor:'pointer', fontSize:11,
            border:`3px solid ${tab===t.key ? C.orangeDark : C.orange}`,
            background:tab===t.key ? C.orange : C.orangeLight,
            color:tab===t.key ? '#fff' : C.orangeDark,
            boxShadow:tab===t.key ? `3px 3px 0 #8B3A1A` : 'none',
          }}>{t.label}</button>
        ))}
      </div>

      {/* ══════════════════════════════════════════════
          TAB: ตัวละคร
      ══════════════════════════════════════════════ */}
      {tab === 'avatar' && (
        <div>
          {/* Preview */}
          <div style={{
            ...pxBox(C.orange,'#FFD4B8','#FFF5EE',C.orangeDark),
            padding:'28px 24px', marginBottom:20,
            display:'flex', flexDirection:'column', alignItems:'center', gap:14,
          }}>
            <PixelPerson
              skin={profile.skin}
              hair={profile.hair}
              outfit={profile.outfit}
              pants={profile.pants}
              hairStyle={profile.hairStyle}
              hat={profile.hat}
              pose={profile.pose}
              scale={7}
            />
            <p style={{ margin:0, fontSize:13, fontFamily:FONT, color:C.text, lineHeight:2 }}>
              {profile.name || '(ยังไม่มีชื่อ)'}
            </p>
          </div>

          {/* Skin tone */}
          <div style={{ ...pxBox('#E8A87C','#FFD4B0','#FFF5EC','#C07838'), padding:16, marginBottom:12 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:'#7B4010' }}>🧑 สีผิว</p>
            <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
              {SKIN_TONES.map(t => <Swatch key={t} color={t} active={profile.skin===t} onClick={() => update('skin',t)}/>)}
            </div>
          </div>

          {/* Hair color */}
          <div style={{ ...pxBox(C.purple,'#DDD6FE','#FAF5FF',C.purpleDark), padding:16, marginBottom:12 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:C.purpleDark }}>💇 สีผม</p>
            <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
              {HAIR_COLORS.map(c => <Swatch key={c} color={c} active={profile.hair===c} onClick={() => update('hair',c)}/>)}
            </div>
          </div>

          {/* Hair style */}
          <div style={{ ...pxBox(C.yellow,'#FDE9B8','#FFFDF5',C.yellowDark), padding:16, marginBottom:12 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:C.yellowDark }}>✂️ ทรงผม</p>
            <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
              {HAIR_STYLES.map(st => (
                <button key={st} onClick={() => update('hairStyle', st)} style={{
                  padding:'10px 16px', fontFamily:FONT, fontSize:11, cursor:'pointer',
                  border:`3px solid ${profile.hairStyle===st ? C.yellowDark : C.yellow}`,
                  background:profile.hairStyle===st ? C.yellow : C.yellowLight,
                  color:C.yellowDark,
                  boxShadow:profile.hairStyle===st ? `2px 2px 0 ${C.yellowDark}` : 'none',
                }}>{HAIR_STYLE_LABELS[st]}</button>
              ))}
            </div>
          </div>

          {/* Hats */}
          <div style={{ ...pxBox(C.blue,'#BFDBFE','#EFF6FF',C.blueDark), padding:16, marginBottom:12 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:C.blueDark }}>หมวก</p>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(105px, 1fr))', gap:10 }}>
              {HATS.map(hat => {
                const active = (profile.hat || 'cap') === hat;
                return (
                  <button key={hat} onClick={() => update('hat', hat)} style={{
                    padding:'10px 8px', fontFamily:FONT, fontSize:10, cursor:'pointer',
                    border:`3px solid ${active ? C.blueDark : C.blue}`,
                    background:active ? C.blue : C.blueLight,
                    color:C.blueDark,
                    boxShadow:active ? `2px 2px 0 ${C.blueDark}` : 'none',
                    display:'flex', flexDirection:'column', alignItems:'center', gap:8,
                  }}>
                    <PixelPerson skin={profile.skin} hair={profile.hair} outfit={profile.outfit} pants={profile.pants} hairStyle={profile.hairStyle} hat={hat} pose={profile.pose} scale={2}/>
                    {HAT_LABELS[hat]}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Standing pose */}
          <div style={{ ...pxBox(C.green,'#CCFBF1','#F0FDFA',C.greenDark), padding:16, marginBottom:12 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:C.greenDark }}>ท่ายืน</p>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(112px, 1fr))', gap:10 }}>
              {POSES.map(pose => {
                const active = (profile.pose || 'neutral') === pose;
                return (
                  <button key={pose} onClick={() => update('pose', pose)} style={{
                    padding:'10px 8px', fontFamily:FONT, fontSize:10, cursor:'pointer',
                    border:`3px solid ${active ? C.greenDark : C.green}`,
                    background:active ? C.greenLight : '#fff',
                    color:C.greenDark,
                    boxShadow:active ? `2px 2px 0 ${C.greenDark}` : 'none',
                    display:'flex', flexDirection:'column', alignItems:'center', gap:8,
                  }}>
                    <PixelPerson skin={profile.skin} hair={profile.hair} outfit={profile.outfit} pants={profile.pants} hairStyle={profile.hairStyle} hat={profile.hat} pose={pose} scale={2}/>
                    {POSE_LABELS[pose]}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* ══════════════════════════════════════════════
          TAB: เปลี่ยนชุด
      ══════════════════════════════════════════════ */}
      {tab === 'outfit' && (
        <div>
          {/* Preview */}
          <div style={{
            ...pxBox(C.orange,'#FFD4B8','#FFF5EE',C.orangeDark),
            padding:'28px 24px', marginBottom:20,
            display:'flex', flexDirection:'column', alignItems:'center', gap:14,
          }}>
            <PixelPerson
              skin={profile.skin}
              hair={profile.hair}
              outfit={profile.outfit}
              pants={profile.pants}
              hairStyle={profile.hairStyle}
              hat={profile.hat}
              pose={profile.pose}
              scale={7}
            />
            <p style={{ margin:0, fontSize:12, fontFamily:FONT, color:C.sub }}>คลิกชุดด้านล่างเพื่อเปลี่ยน</p>
          </div>

          {/* Costume cards */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12 }}>
            {OUTFIT_PRESETS.map(({ color, label }) => {
              const active = profile.outfit === color;
              return (
                <div key={color} onClick={() => update('outfit', color)} style={{
                  ...pxBox(
                    active ? '#1a1a1a' : '#C8B8A8',
                    active ? '#888' : '#E5D5C5',
                    active ? '#fff' : '#FAF6F2',
                    active ? '#1a1a1a' : '#A89888'
                  ),
                  padding:'14px 8px', textAlign:'center', cursor:'pointer',
                  background: active ? color + '22' : '#fff',
                  transition:'transform 0.1s',
                }}
                  onMouseEnter={e => { e.currentTarget.style.transform='translate(-2px,-2px)'; }}
                  onMouseLeave={e => { e.currentTarget.style.transform='none'; }}
                >
                  <PixelPerson
                    skin={profile.skin}
                    hair={profile.hair}
                    outfit={color}
                    pants={profile.pants}
                    hairStyle={profile.hairStyle}
                    hat={profile.hat}
                    pose={profile.pose}
                    scale={4}
                  />
                  <p style={{ margin:'10px 0 0 0', fontSize:11, fontFamily:FONT, color: active ? '#1a1a1a' : C.sub }}>
                    {active ? '✓ ' : ''}{label}
                  </p>
                </div>
              );
            })}
          </div>

          {/* Pants color */}
          <div style={{ ...pxBox(C.green,'#CCFBF1','#F0FDFA',C.greenDark), padding:16, marginTop:16 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:C.greenDark }}>สีกางเกง</p>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:10 }}>
              {PANTS_PRESETS.map(({ color, label }) => {
                const active = (profile.pants || '#54B96D') === color;
                return (
                  <button key={color} onClick={() => update('pants', color)} style={{
                    padding:'10px 6px', cursor:'pointer', fontFamily:FONT, fontSize:10,
                    border:`3px solid ${active ? '#1a1a1a' : '#C8B8A8'}`,
                    background: active ? color + '22' : '#fff',
                    color:C.text,
                    boxShadow:active ? '2px 2px 0 #1a1a1a' : 'none',
                    display:'flex', flexDirection:'column', alignItems:'center', gap:8,
                  }}>
                    <PixelPerson skin={profile.skin} hair={profile.hair} outfit={profile.outfit} pants={color} hairStyle={profile.hairStyle} hat={profile.hat} pose={profile.pose} scale={2}/>
                    {active ? '✓ ' : ''}{label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Custom color */}
          <div style={{ ...pxBox(C.blue,'#BFDBFE','#EFF6FF',C.blueDark), padding:16, marginTop:16 }}>
            <p style={{ margin:'0 0 10px 0', fontSize:12, fontWeight:700, fontFamily:FONT, color:C.blueDark }}>🎨 สีกำหนดเอง</p>
            <div style={{ display:'flex', gap:10, alignItems:'center', flexWrap:'wrap' }}>
              <input
                type="color"
                value={profile.outfit || '#5B8DEF'}
                onChange={e => update('outfit', e.target.value)}
                style={{ width:48, height:48, border:`3px solid ${C.blueDark}`, cursor:'pointer', background:'none', padding:2 }}
              />
              <div>
                <p style={{ margin:0, fontSize:11, fontFamily:FONT, color:C.text }}>เลือกสีเอง</p>
                <p style={{ margin:'4px 0 0 0', fontSize:10, fontFamily:FONT, color:C.sub }}>{profile.outfit || '#5B8DEF'}</p>
              </div>
              <input
                type="color"
                value={profile.pants || '#54B96D'}
                onChange={e => update('pants', e.target.value)}
                style={{ width:48, height:48, border:`3px solid ${C.greenDark}`, cursor:'pointer', background:'none', padding:2 }}
              />
              <div>
                <p style={{ margin:0, fontSize:11, fontFamily:FONT, color:C.text }}>สีกางเกง</p>
                <p style={{ margin:'4px 0 0 0', fontSize:10, fontFamily:FONT, color:C.sub }}>{profile.pants || '#54B96D'}</p>
              </div>
              <div style={{ marginLeft:'auto' }}>
                <PixelPerson
                  skin={profile.skin}
                  hair={profile.hair}
                  outfit={profile.outfit}
                  pants={profile.pants}
                  hairStyle={profile.hairStyle}
                  hat={profile.hat}
                  pose={profile.pose}
                  scale={3}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ══════════════════════════════════════════════
          TAB: ข้อมูล
      ══════════════════════════════════════════════ */}
      {tab === 'info' && (
        <div>
          <div style={{
            ...pxBox(C.purple,'#DDD6FE','#FAF5FF',C.purpleDark),
            padding:20, marginBottom:16,
          }}>
            <div style={{ display:'flex', justifyContent:'center', marginBottom:20 }}>
              <PixelPerson
                skin={profile.skin}
                hair={profile.hair}
                outfit={profile.outfit}
                pants={profile.pants}
                hairStyle={profile.hairStyle}
                hat={profile.hat}
                pose={profile.pose}
                scale={5}
              />
            </div>
            {[
              { label:'ชื่อ',  key:'name', ph:'ชื่อของคุณ',    type:'text'   },
              { label:'อายุ', key:'age',  ph:'อายุ (ปี)',      type:'number' },
            ].map(f => (
              <div key={f.key} style={{ marginBottom:16 }}>
                <label style={{ fontSize:12, color:C.sub, display:'block', marginBottom:7, fontFamily:FONT }}>{f.label}</label>
                <input
                  value={profile[f.key] || ''}
                  onChange={e => update(f.key, e.target.value)}
                  placeholder={f.ph} type={f.type}
                  style={{
                    width:'100%', background:'#FFF5FF',
                    border:`3px solid ${C.purple}`, borderRadius:0,
                    padding:'10px 14px', color:C.text, fontSize:15,
                    boxSizing:'border-box', fontFamily:'inherit',
                    boxShadow:`inset 2px 2px 0 #DDD6FE`,
                  }}
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Save button ── */}
      <button onClick={saveAll} style={{
        width:'100%', padding:'16px', marginTop:8,
        background: saveFlash ? C.green : C.orange,
        color:'#fff', fontFamily:FONT, fontSize:13,
        border:`3px solid ${saveFlash ? C.greenDark : C.orangeDark}`,
        cursor:'pointer',
        boxShadow:`4px 4px 0 ${saveFlash ? C.greenDark : '#8B3A1A'}`,
        transition:'background 0.3s',
      }}>
        {saveFlash ? '✓ บันทึกแล้ว!' : '▶ บันทึก'}
      </button>

    </div>
  );
}
